// Package gen renders everything cellwall writes into a project: the agent Dockerfile, the compose
// file, devcontainer.json, seed configuration, and the per-session gateway state.
//
// Output is deterministic (sorted, no timestamps) so regenerating with the same inputs produces no
// diff, and every generated file carries a content hash so `init` can tell a file it generated and
// nobody touched (safe to regenerate) from one a human edited or never came from cellwall
// (never overwritten without --force).
package gen

import (
	"crypto/sha256"
	"encoding/hex"
	"regexp"
	"strings"
)

// markerRe matches the stamp line, e.g. "# cellwall:generated sha256=<64 hex>" or with "//".
var markerRe = regexp.MustCompile(`^(?:#|//) cellwall:generated sha256=([0-9a-f]{64})$`)

// Stamp prepends a marker line carrying the SHA-256 of body. comment is "#" or "//". If body
// starts with a shebang the marker goes on the second line so the interpreter line stays first.
func Stamp(comment, body string) string {
	sum := sha256.Sum256([]byte(body))
	marker := comment + " cellwall:generated sha256=" + hex.EncodeToString(sum[:]) + "\n"
	if strings.HasPrefix(body, "#!") {
		first, rest, _ := strings.Cut(body, "\n")
		return first + "\n" + marker + rest
	}
	return marker + body
}

// StampState describes what a file's marker says about it.
type StampState int

const (
	// Unstamped means the content has no cellwall marker: it did not come from cellwall.
	Unstamped StampState = iota
	// Pristine means it was generated by cellwall and has not been edited since.
	Pristine
	// Edited means it carries a marker but its body no longer matches: a human changed it.
	Edited
)

func (s StampState) String() string {
	return [...]string{"not generated by cellwall", "generated by cellwall, unmodified", "generated by cellwall, then edited"}[s]
}

// Inspect reads the marker (on the first or second line) and compares the body hash.
func Inspect(content []byte) StampState {
	text := string(content)
	lines := strings.SplitAfter(text, "\n")
	for i := 0; i < len(lines) && i < 2; i++ {
		m := markerRe.FindStringSubmatch(strings.TrimRight(lines[i], "\r\n"))
		if m == nil {
			continue
		}
		body := strings.Join(append(append([]string{}, lines[:i]...), lines[i+1:]...), "")
		sum := sha256.Sum256([]byte(body))
		if hex.EncodeToString(sum[:]) == m[1] {
			return Pristine
		}
		return Edited
	}
	return Unstamped
}
